from pathlib import Path
import json,csv,hashlib,datetime,sys
R=Path(__file__).resolve().parents[1];Q=R/'round1'
def load(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def collect():
 plan=load(Q/'configs/plan.json');designs=load(Q/'rtl/design_manifest.json');ppa=load(Q/'results/hardware/ppa.json');by={x['top']:x for x in ppa};assert len(ppa)==sum(not e['duplicate_of']for e in designs)
 rows=[];scans=[];cases=[]
 for e in designs:
  physical=by[e['duplicate_of']or e['top']];raw=list(csv.DictReader((Q/f'results/{e["case"]}_replay.csv').open()));mi=['hd','minimax','support','physical'].index(e['method']);final=next(x for x in raw if int(x['method'])==mi and x['stage']=='final')
  assert int(final['WCE'])<=e['budget'];rows.append(dict(case=e['case'],method=e['method'],LUT=physical['LUT'],WCE=e['WCE'],budget=e['budget'],merges=len(e['choices']),FF=physical['FF'],CARRY4=physical['CARRY4'],DSP=physical['DSP'],WNS_ns=physical['WNS_ns'],WHS_ns=physical['WHS_ns'],pass_internal_100MHz=physical['pass_internal_100MHz'],dual_output_LUTs=physical['dual_output_LUTs'],MAE_at_lowbits_zero=float(final['MAE_at_lowbits_zero']),error_count_at_lowbits_zero=int(final['error_count_at_lowbits_zero']),inputs=int(final['inputs']),physical_source=e['duplicate_of']or e['top']))
 for c in plan['cases']:
  rr=[r for r in rows if r['case']==c['name']];base=min((x for x in rr if x['method']in['hd','minimax']),key=lambda x:x['LUT']);scan=list(csv.DictReader((Q/f'results/{c["name"]}_replay.csv').open()));scans+=scan
  cases.append(dict(case=c['name'],baseline=base['method'],baseline_LUT=base['LUT'],variants=[dict(method=r['method'],LUT=r['LUT'],gain_vs_best_baseline_pct=100*(base['LUT']-r['LUT'])/base['LUT'],WCE=r['WCE'],timing_pass=r['pass_internal_100MHz'])for r in rr if r['method']in['support','physical']]))
 data=dict(round=1,status='COMPLETE_AWAIT_SCORE',completed=datetime.datetime.now().astimezone().isoformat(),rows=rows,cases=cases,full_domain_scans=len(scans),effective_inputs_evaluated=sum(int(r['inputs'])for r in scans),new_mapped_sources=3,inherited_source='mul12 routed primitive graph and nine exact context tables; existing historical evidence, not newly measured contexts',unique_physical_jobs=len(ppa),hdl=load(Q/'state/rtl_validation.json'),engineering=[dict(issue='Vendor glbl GSR startup holds registers reset until 100 ns; first check at 26 ns failed',repair='testbench starts after 200 ns; all 41300 checks then passed',failed_log='results/hardware/simulation_mul12/simulate.log',scientific_effect='none; functional designs and numeric replay unchanged'),dict(issue='conditional evaluator must order both old and replaced inputs',repair='union dependency order applied before first numeric replay',scientific_effect='pre-execution correctness repair, not a result-dependent algorithm change')],limits=['HD is a prescribed local HD surrogate, not full author QUADOL; neither author-level state-of-the-art gain nor publication readiness follows','Physical results are one deterministic placement and route, same 10ns clock and IO constraints; no multi-seed robustness yet','Hard WCE was checked over complete represented input domain; multiplier low-bit endpoints cover the original 16-bit input domain analytically','MAE and error counts for multipliers refer only to lowbits-zero slice, not the entire 32-bit joint input domain','Two arithmetic families, DSP forbidden; no application throughput or energy claim','Context/RTL/numerical pipelines share the graph parser; scalar crosscheck and vendor primitive simulation add independent execution paths, not formal equivalence'])
 dump(Q/'state/analysis.json',data)
 with(Q/'reports/RESULTS.csv').open('w',newline='')as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 hashes={p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for sub in ['tools','input/legacy_code','round1/configs','round1/src','round1/rtl','round1/graphs','round1/results']for p in(R/sub).rglob('*')if p.is_file()and p.suffix in['.py','.tcl','.json','.cpp','.v','.sv','.xdc','.csv','.hex','.log','.rpt','.stderr']}
 dump(Q/'state/evidence_hashes.json',hashes);print(json.dumps(data['cases'],indent=2));print('scans',data['full_domain_scans'],'inputs',data['effective_inputs_evaluated'],'HDL',sum(x['checks']for x in data['hdl']))
if __name__=='__main__':collect()
